#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100005

char P[MAXN];
int divisors[MAXN];
int num_divisors = 0;

int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;
    if (scanf("%s", P) != 1) return 0;

    for (int i = 1; (long long)i * i <= N; i++) {
        if (N % i == 0) {
            divisors[num_divisors++] = i;
            if (i * i != N && i != 1) {
                divisors[num_divisors++] = N / i;
            }
        }
    }

    qsort(divisors, num_divisors, sizeof(int), cmp_int);

    int target_freq[26];
    int current_freq[26];

    for (int d = 0; d < num_divisors; d++) {
        int L = divisors[d];
        if (L >= N) continue;

        memset(target_freq, 0, sizeof(target_freq));
        for (int i = 0; i < L; i++) {
            target_freq[P[i] - 'a']++;
        }

        int possible = 1;
        for (int i = L; i < N; i += L) {
            memset(current_freq, 0, sizeof(current_freq));
            for (int j = 0; j < L; j++) {
                current_freq[P[i + j] - 'a']++;
            }

            if (memcmp(target_freq, current_freq, sizeof(target_freq)) != 0) {
                possible = 0;
                break;
            }
        }

        if (possible) {
            P[L] = '\0';
            printf("%s\n", P);
            return 0;
        }
    }

    printf("*\n");
    return 0;
}
